solution:
/// Find the time inside window when nobody in calendars is busy.
///
/// A time is a string "HH:MM" on a 24-hour clock: exactly two digits, a colon and two
/// digits, with 00 <= HH <= 23 and 00 <= MM <= 59; "24:00" is also valid and means the
/// end of the day. An interval (start, end) is half-open: from start up to but not
/// including end. calendars holds one vector of busy intervals per person. Busy intervals
/// may be unsorted, overlap, touch each other and extend outside the window; one with
/// start == end is busy for no time at all.
///
/// Return the maximal free intervals inside window (times when no person is busy) whose
/// length is at least min_minutes, sorted by start, each as a (start, end) pair of times
/// in the same "HH:MM" format ("24:00" for the end of the day).
/// Return None if any time (busy or window) is malformed, any busy interval has
/// start > end, the window does not have start < end, or min_minutes < 1.
/// >>> find_free_slots(vec![vec![("09:00", "10:30")], vec![("12:00", "13:00"), ("10:00", "11:00")]], ("08:00", "14:00"), 30)
/// Some(vec![(String::from("08:00"), String::from("09:00")), (String::from("11:00"), String::from("12:00")), (String::from("13:00"), String::from("14:00"))])
/// >>> find_free_slots(vec![vec![("08:30", "09:10")]], ("09:00", "09:20"), 15)
/// Some(vec![])
fn find_free_slots(calendars: Vec<Vec<(&str, &str)>>, window: (&str, &str), min_minutes: i64) -> Option<Vec<(String, String)>> {
    let lo = parse_time(window.0)?;
    let hi = parse_time(window.1)?;
    if lo >= hi || min_minutes < 1 {
        return None;
    }
    let mut busy: Vec<(i64, i64)> = Vec::new();
    for person in &calendars {
        for &(s, e) in person {
            let a = parse_time(s)?;
            let b = parse_time(e)?;
            if a > b {
                return None;
            }
            let (a, b) = (a.max(lo), b.min(hi));
            if a < b {
                busy.push((a, b));
            }
        }
    }
    busy.sort();
    let mut free: Vec<(i64, i64)> = Vec::new();
    let mut cur = lo;
    for &(a, b) in &busy {
        if a > cur {
            free.push((cur, a));
        }
        cur = cur.max(b);
    }
    if cur < hi {
        free.push((cur, hi));
    }
    Some(
        free.into_iter()
            .filter(|&(a, b)| b - a >= min_minutes)
            .map(|(a, b)| (format_time(a), format_time(b)))
            .collect(),
    )
}

fn parse_time(t: &str) -> Option<i64> {
    let bytes = t.as_bytes();
    if bytes.len() != 5 || bytes[2] != b':' {
        return None;
    }
    for &i in &[0usize, 1, 3, 4] {
        if !bytes[i].is_ascii_digit() {
            return None;
        }
    }
    let h = ((bytes[0] - b'0') * 10 + (bytes[1] - b'0')) as i64;
    let m = ((bytes[3] - b'0') * 10 + (bytes[4] - b'0')) as i64;
    if m > 59 || h > 24 || (h == 24 && m != 0) {
        return None;
    }
    Some(h * 60 + m)
}

fn format_time(x: i64) -> String {
    format!("{:02}:{:02}", x / 60, x % 60)
}
